//! `rustorb._native`: the native part of the rustorb Python package.
//!
//! The Python modules of the package (`rustorb.CORBA`,
//! `rustorb.PortableServer`, `rustorb._rt`) implement the IDL to Python
//! mapping on top of the classes here: [`Orb`](orb::Orb), object
//! references ([`ObjRef`](orb::ObjRef)), the POA and its manager. The
//! marshalling follows the TypeCodes of the code generated by
//! `rustorb-idl -bpython` (see [`tc`] and [`value`]).

mod error;
mod orb;
mod poa;
mod tc;
mod value;

use pyo3::prelude::*;

#[pymodule]
fn _native(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add_class::<orb::Orb>()?;
    m.add_class::<orb::ObjRef>()?;
    m.add_class::<poa::Poa>()?;
    m.add_class::<poa::PoaManager>()?;
    m.add_class::<tc::CompiledOp>()?;
    m.add_function(wrap_pyfunction!(poa::current_poa, m)?)?;
    m.add_function(wrap_pyfunction!(poa::current_object_id, m)?)?;
    m.add_function(wrap_pyfunction!(poa::current_reference, m)?)?;
    m.add_function(wrap_pyfunction!(poa::current_servant, m)?)?;
    Ok(())
}
